"""Generate the two size-limit fixture sitemaps.

The Connect IQ simulator rejects a JSON response above 16384 bytes with -402
(measured; see tests/docs/fixture-limits.md). These fixtures pin both sides of
that boundary:

- ``garmin_limit_near`` must serialize to fewer than 16384 bytes and render.
- ``garmin_limit_over`` must serialize to more than 16384 bytes and produce
  the app's S:-402 error view.

The REST body is larger than this .sitemap file because openHAB adds widget
metadata. Tune the element count until ``python -m e2e verify-fixtures --sizes``
reports the sizes in the header of each file. Both files are exempt from the
normal fixture byte budget because they deliberately straddle the limit.

Run from the repository root:

    python tests/fixtures/openhab/generate_size_fixtures.py
"""

from __future__ import annotations

from pathlib import Path

SITEMAPS = Path(__file__).parent / "conf" / "sitemaps"
NEAR_COUNT = 71
OVER_COUNT = 100
PADDING = 40


def render(name: str, label: str, count: int) -> str:
    rows = "\n".join(
        f'\t\tText label="Row {index:04d} ' + ("x" * PADDING) + '"'
        for index in range(1, count + 1)
    )
    return (
        f"// Generated by generate_size_fixtures.py: {count} Text elements.\n"
        f"// The REST JSON size is measured by e2e verify-fixtures --sizes.\n"
        f"sitemap {name} label=\"{label}\" {{\n"
        f"\tFrame label=\"{label}\" {{\n"
        f"{rows}\n"
        f"\t}}\n"
        f"}}\n"
    )


def main() -> None:
    for name, label, count in (
        ("garmin_limit_near", "Limit near", NEAR_COUNT),
        ("garmin_limit_over", "Limit over", OVER_COUNT),
    ):
        path = SITEMAPS / f"{name}.sitemap"
        path.write_text(render(name, label, count), encoding="utf-8", newline="\n")
        print(f"wrote {path} ({count} rows)")


if __name__ == "__main__":
    main()